/* Staff presence uses server-timed 90-second leases, independent of saved workspace data. */
(function(){'use strict';
const api=()=>window.CAGE_BACKEND,profile=()=>api()?.currentProfile?.();
const sid=crypto.randomUUID(); // Each document gets its own lease; closing one tab cannot hide another.
let rows=[],lastSuccess=0,lastActivity=Date.now(),running=false,stopped=true,generation=0,timer=null,drawPending=false;
const labels={online:'Online',away:'Away',offline:'Offline',unknown:'Status unavailable'};
const button=document.createElement('button');button.type='button';button.id='cage-online-button';button.className='secondary-button';button.hidden=true;document.querySelector('.topbar-actions')?.prepend(button);
const dialog=document.createElement('dialog');dialog.id='cage-online-dialog';dialog.className='app-dialog';dialog.setAttribute('aria-labelledby','cage-online-title');dialog.innerHTML='<div class="dialog-heading"><h2 id="cage-online-title">Team availability</h2><button type="button" class="secondary-button" data-presence-close>Close</button></div><p class="cage-online-note">Online means the Hub is open and recently active. Away means a background tab or five minutes without interaction. Active Hub time is estimated for daily totals in an admin-only weekly report. Away/background time is excluded; multiple devices count once. This is not attendance or productivity tracking.</p><p id="cage-online-error" role="status"></p><ul id="cage-online-list"></ul><p class="cage-online-note">Updates about every 30 seconds. Closed or disconnected sessions expire within 90 seconds.</p><button type="button" class="secondary-button" data-presence-refresh>Refresh status</button>';document.body.append(dialog);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusDialog=document.createElement('dialog');statusDialog.id='cage-status-dialog';statusDialog.className='app-dialog';statusDialog.setAttribute('aria-labelledby','cage-status-title');document.body.append(statusDialog);
const reportDialog=document.createElement('dialog');reportDialog.id='cage-presence-report-dialog';reportDialog.className='app-dialog';document.body.append(reportDialog);
const actions=document.createElement('div');actions.className='cage-status-actions';actions.innerHTML='<button type="button" class="secondary-button" id="cage-set-status">Set your status</button><button type="button" class="secondary-button" id="cage-weekly-report" hidden>Weekly online summary</button>';dialog.querySelector('.dialog-heading').after(actions);
function own(){return rows.find(r=>r.id===profile()?.id)||{};}
function showStatus(){const me=own();statusDialog.innerHTML=`<div class="dialog-heading"><h2 id="cage-status-title">Your status</h2><button type="button" class="secondary-button" data-status-close>Close</button></div><form id="cage-status-form"><div class="cage-status-presets">${[['🍽️','Having lunch'],['📅','In a meeting'],['🎯','Focusing'],['🏠','Working remotely'],['🚗','Travelling']].map(([emoji,text])=>`<button type="button" class="secondary-button" data-status-emoji="${emoji}" data-status-message="${text}">${emoji} ${text}</button>`).join('')}</div><label class="field"><span>Emoji</span><input name="emoji_value" maxlength="32" value="${esc(me.emoji||'')}" placeholder="🍽️"></label><label class="field"><span>Status message</span><input name="message_value" maxlength="100" value="${esc(me.message||'')}" placeholder="Having lunch"></label><label class="field"><span>Clear message after</span><select name="clear_after"><option value="30m">30 minutes</option><option value="1h">1 hour</option><option value="4h">4 hours</option><option value="today" selected>Today (CAT)</option><option value="week">This week (CAT)</option><option value="never">Don't clear automatically</option></select></label><label class="field"><span>Availability</span><select name="availability_mode"><option value="auto" ${me.mode!=='away'?'selected':''}>Automatic — green while active</option><option value="away" ${me.mode==='away'?'selected':''}>Set myself Away</option></select></label><p class="cage-online-note">Your message does not change the green indicator. Manual Away stays set until you choose Automatic, even after the message expires.</p><p class="form-error" role="alert"></p><div class="dialog-actions"><button type="button" class="secondary-button" data-status-clear>Clear message</button><button class="primary-button" type="submit">Save status</button></div></form>`;statusDialog.showModal();}
actions.querySelector('#cage-set-status').addEventListener('click',showStatus);
statusDialog.addEventListener('click',async e=>{if(e.target.closest('[data-status-close]'))statusDialog.close();const preset=e.target.closest('[data-status-emoji]');if(preset){const f=statusDialog.querySelector('form');f.elements.emoji_value.value=preset.dataset.statusEmoji;f.elements.message_value.value=preset.dataset.statusMessage;}if(e.target.closest('[data-status-clear]')){const f=statusDialog.querySelector('form');f.elements.emoji_value.value='';f.elements.message_value.value='';f.requestSubmit();}});
statusDialog.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]'),error=f.querySelector('.form-error');if(b.disabled)return;b.disabled=true;error.textContent='';try{await api().presenceStatus(Object.fromEntries(new FormData(f)));await beat();statusDialog.close();}catch(e){error.textContent=e.message||'Could not save status';}finally{b.disabled=false;}});
const hours=n=>{const m=Math.floor(Number(n)/60);return `${Math.floor(m/60)}h ${String(m%60).padStart(2,'0')}m`;};
async function report(week){const target=reportDialog.querySelector('[data-report-content]');target.textContent='Loading weekly summary…';try{const data=await api().presenceWeek(week);target.innerHTML=`<p class="cage-online-note">${esc(data.week_start)} – ${esc(data.week_end)} · CAT. Tracking began ${esc(new Date(data.tracking_started_at).toLocaleString('en-GB',{timeZone:'Africa/Blantyre'}))}. Earlier dates are untracked; the first week may be partial. Durations are rounded down to minutes.</p><div class="cage-report-scroll"><table><thead><tr><th>Member</th>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun','Total'].map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${data.members.map(m=>`<tr><th scope="row">${esc(m.name)}</th>${m.days.map(d=>`<td>${hours(d.seconds)}</td>`).join('')}<td><strong>${hours(m.total_seconds)}</strong></td></tr>`).join('')}</tbody></table></div>`;}catch(e){target.textContent=e.message||'Summary unavailable';}}
actions.querySelector('#cage-weekly-report').addEventListener('click',()=>{if(profile()?.role!=='admin')return;const d=new Date(Date.now()+7200000);d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));const week=d.toISOString().slice(0,10);reportDialog.innerHTML=`<div class="dialog-heading"><h2>Weekly active Hub time</h2><button type="button" class="secondary-button" data-report-close>Close</button></div><p class="cage-online-note">Admin only. Estimated active time, not attendance. The completed Monday–Sunday week is emailed to active admins after Monday 00:05 CAT. Current-week totals are provisional.</p><form><label class="field"><span>Week starting Monday (CAT)</span><input name="week" type="date" required value="${week}"></label><button class="secondary-button">View week</button></form><div data-report-content aria-live="polite"></div>`;reportDialog.showModal();report(week);});
reportDialog.addEventListener('click',e=>{if(e.target.closest('[data-report-close]'))reportDialog.close();});reportDialog.addEventListener('submit',e=>{e.preventDefault();report(e.target.elements.week.value);});
function fresh(){return !stopped&&lastSuccess&&navigator.onLine&&Date.now()-lastSuccess<90000;}
function status(id){return fresh()?rows.find(r=>r.id===id||r.member_id===id)?.status||'unknown':'unknown';}
function draw(){drawPending=false;const known=fresh();button.hidden=stopped||!profile()||profile().role==='shared';const online=known?rows.filter(r=>r.status==='online').length:0;button.innerHTML=`<span class="cage-presence-dot ${known?'online':'unknown'}" aria-hidden="true"></span>${known?online+' online':'Status unavailable'}`;button.title='View team availability';
 for(const el of document.querySelectorAll('[data-presence-member]')){const value=status(el.dataset.presenceMember);const details=fresh()?JSON.stringify(rows.find(r=>r.id===el.dataset.presenceMember||r.member_id===el.dataset.presenceMember)||{}):'';if(el.dataset.presenceState===value&&el.dataset.presenceDetails===details)continue;el.dataset.presenceDetails=details;el.dataset.presenceState=value;const r=rows.find(r=>r.id===el.dataset.presenceMember||r.member_id===el.dataset.presenceMember),custom=fresh()?[r?.emoji,r?.message].filter(Boolean).join(' '):'';const label=labels[value]+(custom?' · '+custom:'');if(el.classList.contains('cage-presence-label'))el.innerHTML=`<span class="cage-presence-dot ${value}" aria-hidden="true"></span>${esc(label)}`;else{el.querySelector('.cage-presence-dot')?.remove();const dot=document.createElement('span');dot.className='cage-presence-dot '+value;dot.setAttribute('role','img');dot.setAttribute('aria-label',label);dot.title=label;el.append(dot);el.querySelector('.cage-status-emoji')?.remove();if(fresh()&&r?.emoji){const emoji=document.createElement('span');emoji.className='cage-status-emoji';emoji.textContent=r.emoji;emoji.title=custom;emoji.setAttribute('aria-label',custom);el.append(emoji);}}}
 document.getElementById('cage-weekly-report').hidden=profile()?.role!=='admin';if(dialog.open){document.getElementById('cage-online-error').textContent=known?'':'Status could not be loaded. Check your connection or try Refresh status.';document.getElementById('cage-online-list').innerHTML=known?[...rows].sort((a,b)=>({online:0,away:1,offline:2}[a.status]-{online:0,away:1,offline:2}[b.status])||a.name.localeCompare(b.name)).map(r=>`<li><span class="cage-presence-dot ${r.status}" aria-hidden="true"></span><strong>${esc(r.name)}${r.id===profile()?.id?' (you)':''}<small class="cage-status-message">${esc([r.emoji,r.message].filter(Boolean).join(' '))}</small></strong><span>${labels[r.status]}</span></li>`).join(''):'';}}
function scheduleDraw(){if(!drawPending){drawPending=true;requestAnimationFrame(draw);}}
async function beat(){if(stopped||running||!profile())return;const token=generation;running=true;try{if(!navigator.onLine)throw Error('offline');const data=await api().presenceHeartbeat(sid,document.hidden||Date.now()-lastActivity>=300000?'away':'online');if(token!==generation)return;rows=data;lastSuccess=Date.now();}catch{if(token===generation)lastSuccess=0;}finally{running=false;draw();}}
async function stop(){const wasActive=!stopped;stopped=true;generation++;clearInterval(timer);lastSuccess=0;rows=[];dialog.close();statusDialog.close();reportDialog.close();draw();if(wasActive&&profile())await Promise.race([api().presenceHeartbeat(sid,'offline').catch(()=>{}),new Promise(resolve=>setTimeout(resolve,1200))]);}
function start(){generation++;stopped=!profile()||profile().active===false||profile().role==='shared';lastSuccess=0;rows=[];lastActivity=Date.now();clearInterval(timer);if(!stopped){beat();timer=setInterval(()=>{if(!profile()){stop();return;}beat();},30000);}draw();}
button.addEventListener('click',()=>{dialog.showModal();draw();beat();});dialog.querySelector('[data-presence-close]').addEventListener('click',()=>dialog.close());dialog.querySelector('[data-presence-refresh]').addEventListener('click',()=>beat());
for(const event of ['pointerdown','keydown','touchstart'])document.addEventListener(event,()=>{const wasAway=Date.now()-lastActivity>=300000;lastActivity=Date.now();if(wasAway)beat();},{passive:true});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)lastActivity=Date.now();beat();});window.addEventListener('online',beat);window.addEventListener('offline',()=>{lastSuccess=0;draw();});window.addEventListener('pagehide',()=>{stop();});window.addEventListener('pageshow',e=>{if(e.persisted)start();});window.addEventListener('cage:session-ready',start);
// Paint only newly rendered availability targets; do not re-render chat or disturb scrolling/drafts.
new MutationObserver(records=>{if(records.some(r=>[...r.addedNodes].some(n=>n.nodeType===1&&(n.matches?.('[data-presence-member]')||n.querySelector?.('[data-presence-member]')))))scheduleDraw();}).observe(document.body,{childList:true,subtree:true});
window.CAGE_PRESENCE={stop,status,refresh:beat};if(profile())start();
})();
